#include<bits/stdc++.h>

using namespace std;

int get(int c00, int c11, int cd)
{                                      
    int len = c00 + c11 + cd;
    int lf = len / 4;
    int rg = 1e8;
    int ans = 1e8;
    while(rg >= lf)
    {
        int mid = (lf + rg) / 2;
        int need_break = max(0, c00 - mid) + max(0, c11 - mid);
        if(need_break + cd / 2 <= mid)
        {
            ans = mid;
            rg = mid - 1;
        }
        else
            lf = mid + 1;
    }
    return ans;
}

void solve()
{
    int n, q;
    cin >> n >> q;
    string s;
    cin >> s;
    vector<int> pref1(n + 1), prefdiff(n);
    for(int i = 0; i < n; i++)
        pref1[i + 1] = pref1[i] + (s[i] - '0');
    for(int i = 0; i + 1 < n; i++)
        prefdiff[i + 1] = prefdiff[i] + (s[i] != s[i + 1]);

    for(int i = 0; i < q; i++)
    {
        int l, r;
        cin >> l >> r;
        if(l == r)
            cout << 3 << "\n";
        else
        {
            int c1 = pref1[r] - pref1[l - 1];
            int cd = prefdiff[r - 1] - prefdiff[l - 1];
            if(s[l - 1] != s[r - 1])
                cd++;
            int c0 = (r - l + 1) - c1;
            int c00 = c0 - (cd / 2);
            int c11 = c1 - (cd / 2);
            cout << get(c00, c11, cd) * 4 - (r - l + 1) << "\n";
        }
    }
}

