#include<bits/stdc++.h>

using namespace std;

const int N = 3010;

vector<pair<int, int>> g[N];
int p[N];
int pe[N];
int used[N];
int n, m;
vector<int> bad_edges;
int cycle[N];
int xs[N], ys[N];

void dfs1(int x)
{
    for(auto [y, i] : g[x])
        if(p[y] == -1)
        {
            p[y] = x;
            pe[y] = i;
            dfs1(y);
        }
        else if(p[x] != y)
            bad_edges.push_back(i);
}

void go_to_root(int x)
{
    while(x != 0)
    {
        cycle[pe[x]] ^= 1;
        x = p[x];
    }
}

void dfs2(int x)
{
    used[x] = true;
    for(auto [y, i] : g[x])
        if(cycle[i] == 0 && !used[y])
            dfs2(y); 
}

void solve()
{
    cin >> n >> m;
    bad_edges.clear();
    for(int i = 0; i < n; i++)
    {
        g[i].clear();
        p[i] = -1;
        pe[i] = -1;
    }
    for(int i = 0; i < m; i++)
    {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        xs[i] = x;
        ys[i] = y;
        g[x].push_back(make_pair(y, i));
        g[y].push_back(make_pair(x, i));
    }

    p[0] = 0;
    dfs1(0);
    sort(bad_edges.begin(), bad_edges.end());
    bad_edges.erase(unique(bad_edges.begin(), bad_edges.end()), bad_edges.end());

    int k = bad_edges.size();
    for(int mask = 1; mask < (1 << k); mask++)
    {
        for(int edge = 0; edge < m; edge++) cycle[edge] = 0;
        for(int bit = 0; bit < k; bit++)
            if((mask >> bit) & 1)
            {                                                               
                go_to_root(xs[bad_edges[bit]]);
                go_to_root(ys[bad_edges[bit]]);
                cycle[bad_edges[bit]] ^= 1;
            }
        for(int vertex = 0; vertex < n; vertex++)
            used[vertex] = 0;
        dfs2(0);
        bool good = true;
        for(int vertex = 0; vertex < n; vertex++)
            if(!used[vertex])
                good = false;
        if(good)
        {
            cout << "YES\n";
            return;
        }
    }
    cout << "NO\n";
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int t;
    cin >> t;
    for(int i = 0; i < t; i++)
        solve();    
}

#include<bits/stdc++.h>

using namespace std;

const int MOD = 998244353;

int add(int x, int y)
{
    x += y;
    while(x >= MOD) x -= MOD;
    while(x < 0) x += MOD;
    return x;   
}

int mul(int x, int y)
{
    return (x * 1ll * y) % MOD;
}

int binpow(int x, int y)
{
    int z = 1;
    while(y > 0)
    {
        if(y % 2 == 1) z = mul(z, x);
        x = mul(x, x);
        y /= 2;
    }
    return z;
}

int inv(int x)
{
    return binpow(x, MOD - 2);
}

const int N = 200043;

int mind[N];
int fact[N];
int ifact[N];

void precalc()
{
    for(int i = 2; i < N; i++)
        for(int j = i; j < N; j += i)
            if(mind[j] == 0)
                mind[j] = i;

    fact[0] = 1;
    for(int i = 1; i < N; i++)
        fact[i] = mul(fact[i - 1], i);
    ifact[N - 1] = inv(fact[N - 1]);
    for(int i = N - 1; i >= 1; i--)
        ifact[i - 1] = mul(ifact[i], i);
}

int choose(int n, int k)
{
    if(n < 0 || n < k || k < 0) return 0;
    return mul(fact[n], mul(ifact[k], ifact[n - k]));
}

int n;

vector<int> factorize(int x)
{
    vector<int> res;
    while(x != 1)
    {
        res.push_back(mind[x]);
        x /= mind[x];
    }
    return res;
}

void gen(const vector<int>& d, int i, long long cur, int m, vector<pair<long long, int>>& res)
{
    if(i == d.size()) res.push_back(make_pair(cur, m));
    else
    {
        gen(d, i + 1, cur, m, res);
        gen(d, i + 1, cur * 1ll * d[i], -m, res);
    }
} 

void solve()
{
    cin >> n;
    vector<pair<pair<long long, int>, int>> edges;
    for(int i = 1; i < n; i++)
    {
        auto f1 = factorize(i);
        auto f2 = factorize(i + 1);
        for(auto x : f2) f1.push_back(x);
        sort(f1.begin(), f1.end());
        f1.erase(unique(f1.begin(), f1.end()), f1.end());
        vector<pair<long long, int>> pos;
        gen(f1, 0, 1, 1, pos);
        for(auto [x, s] : pos)
        {
            if(x == 1) continue;
            edges.push_back(make_pair(make_pair(x, s), i));
        }
    }

    int ans = 1;
    int l = 0;
    sort(edges.begin(), edges.end());
    while(l < edges.size())
    {
        int r = l;
        while(r < edges.size() && edges[r].first.first == edges[l].first.first)
            r++;
        vector<int> e;
        for(int i = l; i < r; i++)
            e.push_back(edges[i].second);
        long long i = edges[l].first.first;
        int m = edges[l].first.second;
        if(m != 0)
        {
            int absent = n / i;
            int cur = mul(fact[n], ifact[n - absent]);
            int lf = 0;
            while(lf < e.size())
            {
                int rg = lf;
                int nxt = e[lf];
                while(rg < e.size() && e[rg] == nxt)
                {
                    rg++;
                    nxt++;
                }
                vector<int> cnt(2);
                for(int k = e[lf]; k <= e[rg - 1] + 1; k++)
                {
                    if(k % i != 0)
                        cnt[k % 2]++;     
                }
                //cout << cnt[0] << " " << cnt[1] << endl;
                cur = mul(cur, choose(cnt[0] + cnt[1], cnt[0]));
                lf = rg;
            }
            //cout << i << " " << cur << endl;
            ans = add(ans, -1 * m * add(cur, -1));
        }
        l = r;
    }
    cout << ans << endl;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    precalc();
    int t = 1;
    //cin >> t;
    for(int i = 0; i < t; i++)
        solve();
}
